  function saveEditor(confirm){if(!writable())return;const row=readEditor(),errors=lineErrors(row,confirm);if(errors.length){errorDialog(errors.join('；')+'。');return;}if(editorNew)row.original={raw:row.raw,spec:row.spec,quantity:row.quantity,unit:'kg'};row.checked=confirm;const i=local.lines.findIndex(l=>l.id===row.id);if(i<0)local.lines.push(row);else local.lines[i]=row;markDirty();closeDialog();render();$('announcer').textContent=confirm?'本行已核对':'本行保存为待核对';}
  function newProduct(){const body=showDialog('创建商品 / 规格（虚构）','new-product');paragraph(body,'只创建本页的标准商品样例，不添加或沿用任何厂家价格。');const fields=el('div','form-stack');control(fields,'product-name','标准商品名 *','text',editDraft.raw);control(fields,'product-spec','商品规格（可留空）','text',editDraft.spec);body.append(fields);dialogActions(button('返回本行',renderEditor),button('创建并绑定',()=>{if(!writable())return;const name=$('product-name').value.trim(),spec=$('product-spec').value.trim();if(!name){errorDialog('标准商品名不能为空。');return;}let p=products.find(p=>p.name===name&&p.spec===spec);if(!p){p={id:'p'+(products.length+1),name,spec};products.push(p);}editDraft.mode='bound';editDraft.productId=p.id;editDraft.spec=spec;renderEditor();},'button primary'));}
  function reviewDelete(){editDraft=readEditor();const body=showDialog('删除当前草稿行','delete-line');paragraph(body,'将删除本草稿中的 '+editDraft.raw+'，原始附件仍保留。冻结行不能删除。');dialogActions(button('保留并返回',renderEditor),button('确认删除',()=>{if(!writable())return;local.lines=local.lines.filter(l=>l.id!==editDraft.id);markDirty();closeDialog();render();},'button danger'));}
