  function reviewImport(kind){if(!writable())return;const body=showDialog(kind==='excel'?'导入 Excel 样例':'拍照 / 相册样例','import');paragraph(body,'只填入虚构原资料和识别明细，不打开真实相机或文件，不上传。Excel 第 4 行演示原单位 g，需要人工核实 kg 数量。');const fields=el('div','form-stack');control(fields,'import-choice','如何处理当前 '+local.lines.length+' 行？','select','append',[['append','追加，保留已有行及核对状态'],['replace','替换当前草稿明细，撤销旧核对']]);body.append(fields);if(local.lines.length)paragraph(body,'同名行仍分别保留，不自动合并；只有明确选替换才清除当前行。');dialogActions(button('取消',closeDialog),button('填入虚构样例',()=>performImport(kind,$('import-choice').value),'button primary'));}
  function performImport(kind,choice){if(!writable())return;const rows=base.map(([raw,spec,quantity],i)=>({raw,spec,quantity:kind==='excel'&&i===3?'20000':quantity,unit:kind==='excel'&&i===3?'g':'kg'}));let attachment=local.parseError&&local.attachments.at(-1)?.kind===kind?local.attachments.at(-1):null;if(!attachment){attachment={id:'F'+(local.attachments.length+1),name:'虚构采购单_'+(kind==='excel'?'原表.xlsx':'原图.jpg'),kind,hospitalName:hospitals[local.root.hospital]?.name||'医院',date:today,rows};local.attachments.push(attachment);}
    if($('demo-parse').value==='failure'){local.parseError=true;message='样例解析失败；原资料已保留，原有 '+local.lines.length+' 行没有被覆盖。';warn=true;dirty=true;closeDialog();render();return;}
    const imported=rows.map((raw,i)=>({id:'L'+(++lineNo),raw:raw.raw,spec:raw.spec,quantity:raw.unit==='kg'?(i===3?'2.00':raw.quantity):'',unit:'kg',mode:i===4?'custom':'bound',productId:i===4?'':'p'+(i+1),remark:'',checked:false,original:clone(raw),conversionConfirmed:raw.unit==='kg'}));local.lines=choice==='replace'?imported:local.lines.concat(imported);local.parseError=false;dirty=true;message='已'+(choice==='replace'?'明确替换':'追加')+' 5 行虚构识别结果，请逐行核对；未自动换算数量或确认商品。';warn=false;closeDialog();tab='lines';render();$('phone-scroll').scrollTop=0;}
  function reviewFreeze(){if(!writable())return;const errors=freezeErrors();if(errors.length){message=errors.join('\n');warn=true;render();$('phone-scroll').scrollTop=0;return;}const body=showDialog('冻结前整单复核 · R'+local.revision,'freeze');paragraph(body,hospitals[local.root.hospital].name+' · '+hospitals[local.root.hospital].purchasers.find(([id])=>id===local.root.purchaser)[1]);paragraph(body,'实际接收 '+local.root.received+'；'+(local.root.created?'本单账期快照 ':'创建时账期 ')+(local.root.created?local.root.term:hospitals[local.root.hospital].term)+' 天；'+(local.root.source==='sales'?'销售代录':'医院提交')+'。');const list=el('ol','freeze-list');local.lines.forEach((line,i)=>list.append(el('li','',(i+1)+'. '+productName(line)+' / '+(line.spec||'规格未提供')+' / '+qty(fraction(line.quantity))+' kg'+(line.mode==='custom'?' · 本次自定义':''))));body.append(list,el('div','freeze-total',local.lines.length+' 行 · '+totalText()));paragraph(body,'冻结后不能直接改行或解冻覆盖；修改须创建下一修订。这里只在本页演示，不生成厂家链接或真实保存。');const fields=el('div','form-stack'),ack=check(fields,'freeze-ack','我已对照原资料核实全部采购行及 kg 数量。');body.append(fields);const confirm=button('确认冻结 R'+local.revision,()=>{if(!ack.checked)return;prepare('freeze');},'button primary');confirm.id='confirm-freeze';confirm.disabled=true;ack.addEventListener('change',()=>confirm.disabled=!ack.checked);dialogActions(button('返回校对',closeDialog),confirm);}
  function reviewRevision(){if(!revisable())return;const body=showDialog('创建下一采购修订 R'+(local.revision+1),'revision');paragraph(body,'复制 R'+local.revision+' 冻结明细为新草稿，重新逐行核对、冻结后再询价。根订单接收日 '+local.root.received+' 和 '+local.root.term+' 天账期不重新起算。');paragraph(body,local.tasks||local.quotes?'旧修订现有 '+local.tasks+' 个厂家任务、'+local.quotes+' 个医院报价版本将退出当前使用；旧链接不能继续填，旧医院报价不能再发送或确认，内容与历史保留。':'当前尚未发起厂家任务；即便没有链接，也不能直接解冻覆盖原行。');paragraph(body,'不提供作废新修订并恢复旧修订的入口；误建时改正当前草稿。');dialogActions(button('保留当前修订',closeDialog),button('确认创建 R'+(local.revision+1),()=>prepare('revise'),'button primary'));}
  function prepare(type){if(type==='revise'?!revisable():!writable())return;const errors=type==='freeze'?freezeErrors():type==='save'?rootErrors():[];if(errors.length){closeDialog();message=errors.join('\n');warn=true;render();$('phone-scroll').scrollTop=0;return;}const request={key:'DEMO-PURCHASE-'+String(++requestNo).padStart(3,'0'),type,user,expectedVersion:local.version,revision:local.revision,payload:clone(local)};closeDialog();const outcome=$('demo-outcome').value;
    if(outcome==='failure'){message='本次明确失败，未保存或冻结。输入仍在，可核对后重试。';warn=true;render();return;}
    if(outcome==='conflict'){server.version++;if(server.status==='draft'&&server.lines.length){server.lines[0].quantity='31.00';server.lines[0].checked=false;}else if(server.status==='frozen'){server.history.push({revision:server.revision,lines:clone(server.lines),root:clone(server.root),attachments:clone(server.attachments),tasks:server.tasks,quotes:server.quotes,superseded:true});server.revision++;server.status='draft';server.lines=server.lines.map(l=>({...l,checked:false}));server.tasks=0;server.quotes=0;}conflict=true;message='PC 已保存了更新的草稿，本次未覆盖。你的本机内容仍保留，请先对照最新版本。';warn=true;render();return;}
    if(outcome==='handoff'){if(local.root.created){server.root.owner=user==='lin'?'chen':'lin';local.root.owner=server.root.owner;server.version++;}else if(local.root.hospital)hospitals[local.root.hospital].owner=user==='lin'?'chen':'lin';message='提交期间负责人或医院归属变化，本次未保存；需按最新权限重新核对。';warn=true;render();return;}
    if(outcome==='unknown'){pending=request;message='请求 '+request.key+' 结果未知。先核对同一次请求，暂不修改、换场景或重复提交。';warn=true;render();return;}
    commit(request);}
  function commit(request){if(receipts.has(request.key))return;if(!readable()||request.user!==user||!owner()){message='当前身份或订单负责人已变化，本次未保存。';warn=true;render();return;}if(server.version!==request.expectedVersion||server.revision!==request.revision){conflict=true;message='当前草稿版本已变化，原输入保留；请对照最新内容。';warn=true;render();return;}if(request.type==='revise'&&server.status!=='frozen'||request.type!=='revise'&&server.status!=='draft'){message='状态已变化，本次操作未执行，请重新核对。';warn=true;render();return;}
    if(request.type==='revise'){const old={revision:server.revision,lines:clone(server.lines),attachments:clone(server.attachments),root:clone(server.root),tasks:server.tasks,quotes:server.quotes,superseded:true};server.history.push(old);server.revision++;server.status='draft';server.lines=server.lines.map(l=>({...l,checked:false}));server.tasks=0;server.quotes=0;}else{const data=request.payload;const errors=rootErrors(data.root);if(errors.length){message=errors.join('\n');warn=true;render();return;}server=clone(data);if(!server.root.created){server.root.created=true;server.root.id='CG-20261021-DEMO';server.root.owner=user;server.root.term=hospitals[server.root.hospital].term;}if(request.type==='freeze')server.status='frozen';}
    server.version++;local=clone(server);dirty=false;pending=null;conflict=false;lastReceipt={key:request.key,type:request.type,revision:local.revision};receipts.set(request.key,clone(lastReceipt));message=(request.type==='freeze'?'R'+local.revision+' 已在本页演示冻结。':request.type==='revise'?'R'+local.revision+' 草稿已创建；旧冻结内容及失效链路历史保留。':'草稿已在本页演示暂存，未冻结。')+'\n回执 '+request.key+'；不代表真实保存。';warn=false;render();$('phone-scroll').scrollTop=0;}
  function verifyPending(){if(!pending||!readable())return;const request=pending;pending=null;commit(request);}
  function showConflict(){if(!readable()||!conflict)return;const body=showDialog('对照最新草稿','conflict');paragraph(body,'本机保存冲突版本 '+local.version+'；PC 当前版本 '+server.version+'。R 修订号与保存冲突版本不同。');paragraph(body,'本机：'+local.lines.map(l=>l.raw+' '+(l.quantity||'待核实')+' kg').join('；'));paragraph(body,'PC：'+server.lines.map(l=>l.raw+' '+(l.quantity||'待核实')+' kg').join('；'));const fields=el('div','form-stack'),ack=check(fields,'conflict-ack','放弃本机未暂存更改，载入 PC 最新草稿并重新校对。');body.append(fields);const load=button('载入最新草稿',()=>{if(!ack.checked||!readable())return;local=clone(server);dirty=false;conflict=false;message='已显式载入 PC 最新草稿，请核实变化后再保存或冻结。';warn=false;closeDialog();render();},'button primary');load.id='load-latest';load.disabled=true;ack.addEventListener('change',()=>load.disabled=!ack.checked);dialogActions(button('保留本机内容',closeDialog),load);}
  function showRevisions(){if(!readable())return;const body=showDialog('采购修订历史','history'),entries=clone(local.history);if(['frozen','completed'].includes(local.status))entries.push({revision:local.revision,lines:clone(local.lines),superseded:false,tasks:local.tasks,quotes:local.quotes});if(!entries.length)paragraph(body,'当前 R'+local.revision+' 仍是草稿，尚无冻结修订。');entries.forEach(item=>{const n=el('section','history-entry');n.append(el('h3','','R'+item.revision+' · '+(item.superseded?'已被替代，历史只读':'当前冻结内容')),el('p','',item.lines.length+' 行 · '+totalText(item.lines)),el('p','',item.lines.map(l=>l.raw+' '+l.quantity+' kg').join('；')));if(item.superseded)n.append(el('p','','原 '+item.tasks+' 个厂家任务、'+item.quotes+' 个医院报价退出当前使用；历史保留，不恢复旧链接或旧确认。'));body.append(n);});dialogActions(button('返回当前采购单',closeDialog,'button primary'));}
  function nextInquiry(){info('手机厂家询价',['手机询价为当前审阅项，可查看两个厂家任务、链接及逐行比价。','下面打开独立虚构样例，不传递本页冻结状态，也不生成真实厂家链接。']);const a=el('a','','打开手机询价原型（独立样例） →');a.href=link('sales-mini-inquiry.html');$('dialog-body').append(a);a.addEventListener('click',e=>{e.preventDefault();leave(a.href);});}
  function leave(url){if(pending){info('先核对本次请求',['请求结果仍未知，请关闭此说明并核对同一次请求；本页内不重复提交或切换场景。']);return;}if(dirty){const body=showDialog('还有本机未暂存内容','leave');paragraph(body,'继续校对会保留输入；放弃并离开只会丢弃本页的虚构改动，不影响其他页面。');dialogActions(button('继续校对',closeDialog,'button primary'),button('放弃并离开',()=>location.href=url,'button danger'));return;}location.href=url;}
  function reset(kind){scenario=kind;server=fixture(kind);local=clone(server);tab=kind==='new'?'info':'lines';dirty=false;pending=null;conflict=false;message='';warn=false;lastReceipt=null;zoom=1;lineNo=5;closeDialog();Object.keys(positions).forEach(k=>positions[k]=0);render();$('phone-scroll').scrollTop=0;}
