  $('close-dialog').addEventListener('click',requestClose);$('work-dialog').addEventListener('cancel',event=>{event.preventDefault();requestClose();});$('view-revisions').addEventListener('click',showRevisions);$('back-workbench').addEventListener('click',()=>leave(link('sales-mini.html')));$('demo-scenario').addEventListener('change',changeScenario);
  $('demo-user').addEventListener('change',()=>{if(pending)return;user=$('demo-user').value;local=clone(server);if(!local.root.created){server=fixture('new');local=clone(server);}dirty=false;conflict=false;message='';warn=false;closeDialog();render();});$('demo-session').addEventListener('change',()=>{session=$('demo-session').value;closeDialog();render();});
